// Des: Fresh environment for spawned commands (Windows registry merge, PATH merge, diff)
// Flo: read machine + user + volatile Environment from the registry > expand %VAR% (REG_EXPAND_SZ only) > user over machine > volatile over both, only for names they set (USERNAME) > PATH = machine;user + old session-only entries > put into the env map
// I/O: env map (copy of the app's start env) > same map with changes made after the app started; two maps > names that differ
// ===================================================================
const std = @import("std"); const builtin = @import("builtin");
pub const Map = std.process.Environ.Map;
pub const Pair = struct { name: []const u8, valu: []const u8, expa: bool = false };
const CF = .{ .path = "PATH", .mach_subk = "SYSTEM\\CurrentControlSet\\Control\\Session Manager\\Environment", .user_subk = "Environment", .vola_subk = "Volatile Environment", .hklm = 0x80000002, .hkcu = 0x80000001, .key_read = 0x20019, .nums_maxz = 4096, .name_buff = 16384, .data_buff = 8192, .data_maxz = 1024 * 1024, .more_data = 234, .no_more = 259, .reg_sz = 1, .reg_expa = 2, .trim = " \t\r\n" };
const SEPA: u8 = if (builtin.os.tag == .windows) ';' else ':';
const winz = if (builtin.os.tag == .windows) struct { extern "advapi32" fn RegOpenKeyExW(hKey: usize, lpSubKey: [*:0]const u16, ulOptions: u32, samDesired: u32, phkResult: *usize) callconv(.winapi) i32; extern "advapi32" fn RegEnumValueW(hKey: usize, dwIndex: u32, lpValueName: [*]u16, lpcchValueName: *u32, lpReserved: ?*u32, lpType: ?*u32, lpData: ?[*]u8, lpcbData: ?*u32) callconv(.winapi) i32; extern "advapi32" fn RegCloseKey(hKey: usize) callconv(.winapi) i32; } else struct {};
fn pathNorm(strz: []const u8) []const u8 { return std.mem.trimEnd(u8, std.mem.trim(u8, strz, CF.trim), "\\/"); }
fn pathSame(left: []const u8, righ: []const u8) bool { return if (builtin.os.tag == .windows) std.ascii.eqlIgnoreCase(pathNorm(left), pathNorm(righ)) else std.mem.eql(u8, pathNorm(left), pathNorm(righ)); }
fn pathHas(list: []const []const u8, item: []const u8) bool { for (list) |entr| if (pathSame(entr, item)) return true; return false; }
// PATH = every entry of `lead` in order, then the entries of `proc` not already there (session-only additions survive)
pub fn pathMerg(allo: std.mem.Allocator, lead: []const []const u8, proc: []const u8) ![]u8 { var list: std.ArrayList([]const u8) = .empty; defer list.deinit(allo); for (lead) |srcz| { var iter = std.mem.splitScalar(u8, srcz, SEPA); while (iter.next()) |item| { if (std.mem.trim(u8, item, CF.trim).len == 0 or pathHas(list.items, item)) continue; try list.append(allo, item); } } var iter = std.mem.splitScalar(u8, proc, SEPA); while (iter.next()) |item| { if (std.mem.trim(u8, item, CF.trim).len == 0 or pathHas(list.items, item)) continue; try list.append(allo, item); } var outz: std.ArrayList(u8) = .empty; errdefer outz.deinit(allo); for (list.items, 0..) |item, indx| { if (indx > 0) try outz.append(allo, SEPA); try outz.appendSlice(allo, item); } return outz.toOwnedSlice(allo); }
// %NAME% -> value from the map; an unknown name stays as written
pub fn expaText(allo: std.mem.Allocator, srcz: []const u8, mapz: *const Map) ![]u8 { var outz: std.ArrayList(u8) = .empty; errdefer outz.deinit(allo); var indx: usize = 0; while (indx < srcz.len) { if (srcz[indx] == '%') { if (std.mem.indexOfScalarPos(u8, srcz, indx + 1, '%')) |clos| { const name = srcz[indx + 1 .. clos]; if (name.len > 0 and Map.validateKeyForFetch(name)) { if (mapz.get(name)) |valz| { try outz.appendSlice(allo, valz); indx = clos + 1; continue; } } } } try outz.append(allo, srcz[indx]); indx += 1; } return outz.toOwnedSlice(allo); }
fn valuFina(allo: std.mem.Allocator, pair: Pair, mapz: *const Map) ![]const u8 { return if (pair.expa) try expaText(allo, pair.valu, mapz) else pair.valu; }
fn listHas(list: []const Pair, name: []const u8) bool { for (list) |pair| if (std.ascii.eqlIgnoreCase(pair.name, name)) return true; return false; }
fn pathPair(list: []const Pair) ?Pair { for (list) |pair| if (Map.validateKeyForFetch(pair.name) and std.ascii.eqlIgnoreCase(pair.name, CF.path)) return pair; return null; }
// user over machine for every name; PATH is joined, never replaced; names missing in the registry are left alone
pub fn mergApply(allo: std.mem.Allocator, mapz: *Map, mach: []const Pair, user: []const Pair, vola: []const Pair) !void { for ([_][]const Pair{ mach, user, vola }, 0..) |list, laye| { for (list) |pair| { if (pair.name.len == 0 or pair.valu.len == 0 or !Map.validateKeyForPut(pair.name) or std.ascii.eqlIgnoreCase(pair.name, CF.path)) continue; if (laye == 2 and !listHas(mach, pair.name) and !listHas(user, pair.name)) continue; try mapz.put(pair.name, try valuFina(allo, pair, mapz)); } } const mach_path = if (pathPair(mach)) |pair| try valuFina(allo, pair, mapz) else ""; const user_path = if (pathPair(user)) |pair| try valuFina(allo, pair, mapz) else ""; if (mach_path.len == 0 and user_path.len == 0) return; const merg = try pathMerg(allo, &.{ mach_path, user_path }, mapz.get(CF.path) orelse ""); try mapz.put(CF.path, merg); }
fn regiRead(allo: std.mem.Allocator, hive: usize, subk: [*:0]const u16) ![]Pair { var outz: std.ArrayList(Pair) = .empty; var keyz: usize = 0; if (winz.RegOpenKeyExW(hive, subk, 0, CF.key_read, &keyz) != 0) return outz.toOwnedSlice(allo); defer _ = winz.RegCloseKey(keyz); const name_bufz = try allo.alloc(u16, CF.name_buff); defer allo.free(name_bufz); var data_bufz = try allo.alloc(u16, CF.data_buff / 2); defer allo.free(data_bufz); var indx: u32 = 0; while (indx < CF.nums_maxz) { var name_leng: u32 = CF.name_buff; var kind: u32 = 0; var data_leng: u32 = @intCast(data_bufz.len * 2); const resu = winz.RegEnumValueW(keyz, indx, name_bufz.ptr, &name_leng, null, &kind, @ptrCast(data_bufz.ptr), &data_leng); if (resu == CF.no_more) break; if (resu == CF.more_data) { if (data_leng > CF.data_maxz) { indx += 1; continue; } allo.free(data_bufz); data_bufz = try allo.alloc(u16, data_leng / 2 + 2); continue; } indx += 1; if (resu != 0 or (kind != CF.reg_sz and kind != CF.reg_expa) or name_leng == 0) continue; const text = std.mem.sliceTo(data_bufz[0 .. data_leng / 2], 0); const name = std.unicode.wtf16LeToWtf8Alloc(allo, name_bufz[0..name_leng]) catch continue; const valu = std.unicode.wtf16LeToWtf8Alloc(allo, text) catch continue; try outz.append(allo, .{ .name = name, .valu = valu, .expa = kind == CF.reg_expa }); } return outz.toOwnedSlice(allo); }
// Windows: pull in what changed in the registry after this app started; other systems: nothing (the env is fixed at launch)
pub fn applyFres(allo: std.mem.Allocator, mapz: *Map) void { if (builtin.os.tag != .windows) return; const mach = regiRead(allo, CF.hklm, std.unicode.utf8ToUtf16LeStringLiteral(CF.mach_subk)) catch return; const user = regiRead(allo, CF.hkcu, std.unicode.utf8ToUtf16LeStringLiteral(CF.user_subk)) catch return; const vola = regiRead(allo, CF.hkcu, std.unicode.utf8ToUtf16LeStringLiteral(CF.vola_subk)) catch &[_]Pair{}; mergApply(allo, mapz, mach, user, vola) catch {}; }
// names whose value is new or different in `fres` compared with `base` (names only, never values)
pub fn diffNames(allo: std.mem.Allocator, base: *const Map, fres: *const Map) ![][]const u8 { var outz: std.ArrayList([]const u8) = .empty; errdefer outz.deinit(allo); var iter = fres.iterator(); while (iter.next()) |entr| { const old = base.get(entr.key_ptr.*); if (old == null or !std.mem.eql(u8, old.?, entr.value_ptr.*)) try outz.append(allo, entr.key_ptr.*); } return outz.toOwnedSlice(allo); }
